        state->dataHVACVarRefFlow->VRF.allocate(numVRFCond);
        state->dataHVACVarRefFlow->CoolCombinationRatio.allocate(1);
        state->dataHVACVarRefFlow->HeatCombinationRatio.allocate(1);

